// @S-WH-06 — git connections (the credential vault): the empty page, a token connection (create,
// "secret set" after a reload, a replaced secret), a key generated by Work Hub pinned on first
// use, an uploaded key with a passphrase, a token revoked at the host, the token exposed to the
// agent as an env variable, grants, and deleting a connection a remote still uses (FR-1, FR-1a,
// FR-2, FR-10, FR-11). Every connection uses the `generic` provider against the stand's fake git
// host (git.test).
import fs from 'node:fs';
import type { Page } from '@playwright/test';
import {
  addAuthorizedKey,
  attachRemote,
  connectionSecretFile,
  createWorkspace,
  dockerExec,
  expect,
  FAKE_GIT_BASE,
  FAKE_GIT_HTTP,
  FAKE_GIT_SSH,
  FAKE_PAT,
  FAKE_PAT_USER,
  fakeGit,
  fakeLoginInContainer,
  gitMain,
  setFakePat,
  setGrants,
  signedInPage,
  signIn,
  test,
  workstreamContainer,
  type Connection,
  type WhApi,
  type WorkstreamSummary,
} from './fixtures';

test.describe.configure({ timeout: 1_800_000 });

const row = (page: Page, name: string) => page.getByTestId('connection-row').filter({ hasText: name });

async function connections(api: WhApi): Promise<Connection[]> {
  return api.expectStatus<Connection[]>('GET', '/api/v1/connections', 200);
}

async function connectionByName(api: WhApi, name: string): Promise<Connection> {
  const c = (await connections(api)).find((x) => x.name === name);
  if (!c) throw new Error(`no connection "${name}"`);
  return c;
}

/** "+ Add connection" → the generic provider → server URL and name → `auth`. */
async function startAdd(page: Page, name: string, auth: 'ssh_generated' | 'ssh_uploaded' | 'pat'): Promise<void> {
  await page.getByTestId('add-connection').click();
  const dialog = page.getByTestId('add-connection-dialog');
  await expect(dialog).toBeVisible();
  await dialog.locator('[data-testid="connection-provider"][data-provider-id="generic"]').click();
  await dialog.getByTestId('connection-base-url').fill(FAKE_GIT_BASE);
  await dialog.getByTestId('connection-name').fill(name);
  await dialog.getByTestId(`connection-auth-${auth}`).check();
}

/** On a Test view: the repository URL, Test, then "Trust and pin" when the host key is new. */
async function runTest(page: Page, scope: string, url: string, expectPin: boolean): Promise<void> {
  const box = page.getByTestId(scope);
  await box.getByTestId('connection-test-url').fill(url);
  await box.getByTestId('connection-test-run').click();
  if (expectPin) {
    const prompt = box.getByTestId('host-key-prompt');
    await expect(prompt).toBeVisible({ timeout: 120_000 });
    await expect(prompt).toContainText('First connection to git.test');
    await expect(box.getByTestId('host-key-fingerprint')).toHaveText(/^SHA256:/);
    await box.getByTestId('host-key-trust').click();
  }
  await expect(box.getByTestId('connection-test-ok')).toBeVisible({ timeout: 120_000 });
}

/** Opens a workstream through the API (the workspace's agent must be logged in). */
async function openStream(api: WhApi, workspaceId: string, name: string): Promise<WorkstreamSummary> {
  return api.expectStatus<WorkstreamSummary>('POST', `/api/v1/workspaces/${workspaceId}/workstreams`, 201, { name });
}

/** `tmux show-environment` of the chat session of a workstream. */
function chatEnv(streamId: string): string {
  return dockerExec(workstreamContainer(streamId), ['tmux', 'show-environment', '-t', '=chat']).stdout;
}

test('@S-WH-06 @mode-a git connections: vault, keys, tokens, expose, grants and delete', async ({ browser, stand, api }) => {
  const me = await signIn(stand, api);
  const { context, page, offOrigin } = await signedInPage(browser, stand, api);

  // Every API response the page receives, to prove that no secret ever comes back.
  const responses: Promise<string>[] = [];
  context.on('response', (res) => {
    if (res.url().includes('/api/v1/')) responses.push(res.text().catch(() => ''));
  });
  const responseLeaks = async (needles: string[]): Promise<string[]> => {
    const texts = await Promise.all(responses);
    return needles.filter((n) => texts.some((t) => t.includes(n)));
  };

  // The PAT the fake host accepts right now (step 2 rotates it).
  let pat = FAKE_PAT;
  let vaultId = '';
  let otherId = '';

  try {
    await test.step('1. empty state (FR-1)', async () => {
      expect(await connections(api)).toEqual([]);
      await page.goto('/#/connections');
      await expect(page.getByTestId('connections-empty')).toHaveText('No connections yet. Work Hub works fully without them.');
      // The user menu leads here too.
      await page.goto('/#/');
      await page.getByTestId('user-menu').click();
      await page.getByTestId('menu-connections').click();
      await expect(page).toHaveURL(/#\/connections$/);
      await expect(page.getByTestId('connections-empty')).toBeVisible();
    });

    await test.step('2. a token connection: create and test, "secret set" after a reload, edit replaces the secret (FR-1, FR-2, FR-11)', async () => {
      // FR-2: one dialog for every provider; a provider with a fixed server hides the URL field.
      const providers = await api.expectStatus<{ id: string; baseUrlFixed: string | null }[]>('GET', '/api/v1/connection-providers', 200);
      expect(providers.map((p) => p.id)).toContain('generic');
      const fixed = providers.find((p) => p.baseUrlFixed !== null);
      await page.getByTestId('add-connection').click();
      const dialog = page.getByTestId('add-connection-dialog');
      if (fixed) {
        await dialog.locator(`[data-testid="connection-provider"][data-provider-id="${fixed.id}"]`).click();
        await expect(dialog.getByTestId('connection-base-url')).toHaveCount(0);
        await expect(dialog.getByTestId('connection-name')).toBeVisible();
      }
      await dialog.getByRole('button', { name: 'Cancel' }).click();
      await expect(dialog).toHaveCount(0);

      await startAdd(page, 'Fake PAT', 'pat');
      await dialog.getByTestId('connection-username').fill(FAKE_PAT_USER);
      await dialog.getByTestId('connection-token').fill(pat);
      await dialog.getByTestId('add-connection-save').click();
      await runTest(page, 'add-connection-dialog', FAKE_GIT_HTTP, false);
      await dialog.getByTestId('add-connection-done').click();
      await expect(dialog).toHaveCount(0);

      await page.reload();
      await expect(row(page, 'Fake PAT')).toContainText('secret set');
      await expect(row(page, 'Fake PAT').getByTestId('connection-status')).toHaveText('Connected');
      const created = await connectionByName(api, 'Fake PAT');
      expect(created).toMatchObject({ provider: 'generic', authMethod: 'pat', username: FAKE_PAT_USER, secretSet: true, status: 'ok' });
      expect(JSON.stringify(await connections(api))).not.toContain(pat);
      expect(JSON.stringify(await api.get(`/api/v1/connections/${created.id}`))).not.toContain(pat);

      // The host rotates the token; Edit → "Update token…" replaces it and the status starts over.
      pat = 'scenario-pat-2';
      setFakePat(stand, pat);
      await row(page, 'Fake PAT').getByTestId('connection-edit').click();
      const edit = page.getByTestId('edit-connection-dialog');
      await edit.getByTestId('update-secret').click();
      await edit.getByTestId('connection-token').fill(pat);
      await edit.getByTestId('edit-connection-save').click();
      await expect(edit).toHaveCount(0);
      await expect(row(page, 'Fake PAT').getByTestId('connection-status')).toHaveText('Not tested');
      await row(page, 'Fake PAT').getByTestId('connection-test').click();
      await runTest(page, 'test-connection-dialog', FAKE_GIT_HTTP, false);
      await page.getByTestId('test-connection-dialog').getByRole('button', { name: 'Close' }).last().click();
      await expect(row(page, 'Fake PAT').getByTestId('connection-status')).toHaveText('Connected');
      const all = JSON.stringify(await connections(api));
      expect(all).not.toContain(pat);
      expect(all).not.toContain(FAKE_PAT);
    });

    await test.step('3. a key generated by Work Hub, pinned on first use; no private key in any response (FR-1a)', async () => {
      await startAdd(page, 'Fake SSH', 'ssh_generated');
      const dialog = page.getByTestId('add-connection-dialog');
      await dialog.getByTestId('add-connection-save').click();
      const publicKey = dialog.getByTestId('connection-public-key');
      await expect(publicKey).toHaveValue(/^ssh-ed25519 /, { timeout: 60_000 });
      addAuthorizedKey(stand, await publicKey.inputValue());
      await runTest(page, 'add-connection-dialog', FAKE_GIT_SSH, true);
      await dialog.getByTestId('add-connection-done').click();

      const ssh = await connectionByName(api, 'Fake SSH');
      expect(ssh).toMatchObject({ authMethod: 'ssh_generated', status: 'ok' });
      expect(ssh.hostKeyFingerprint).toMatch(/^SHA256:/);
      expect(ssh.keyFingerprint).toMatch(/^SHA256:/);
      // A second test needs no pin.
      const again = await api.expectStatus<{ result: string }>('POST', `/api/v1/connections/${ssh.id}/test`, 200, { url: FAKE_GIT_SSH });
      expect(again.result).toBe('ok');
      await api.get(`/api/v1/connections/${ssh.id}`);
      expect(await responseLeaks(['PRIVATE KEY'])).toEqual([]);
      expect(JSON.stringify(await connections(api))).not.toContain('PRIVATE KEY');
    });

    await test.step('4. an uploaded key with a passphrase (FR-1a)', async () => {
      const make = fakeGit(
        stand,
        'rm -f /tmp/scn-upload /tmp/scn-upload.pub && ssh-keygen -q -t ed25519 -N scn-passphrase -C scn-upload -f /tmp/scn-upload && cat /tmp/scn-upload',
      );
      expect(make.status, make.stderr).toBe(0);
      const privateKey = make.stdout;
      addAuthorizedKey(stand, fakeGit(stand, 'cat /tmp/scn-upload.pub').stdout);
      const keyBody = privateKey.split(/\r?\n/)[2];
      expect(keyBody.length).toBeGreaterThan(20);

      await startAdd(page, 'Fake upload', 'ssh_uploaded');
      const dialog = page.getByTestId('add-connection-dialog');
      await dialog.getByTestId('connection-private-key').fill(privateKey);
      await dialog.getByTestId('connection-passphrase').fill('scn-passphrase');
      await dialog.getByTestId('add-connection-save').click();
      await dialog.getByTestId('connection-test-url').fill(FAKE_GIT_SSH);
      await dialog.getByTestId('connection-test-run').click();
      // The host key is pinned per connection: trust it again when asked.
      const pin = dialog.getByTestId('host-key-prompt');
      const ok = dialog.getByTestId('connection-test-ok');
      await expect(pin.or(ok)).toBeVisible({ timeout: 120_000 });
      if (await pin.isVisible()) await dialog.getByTestId('host-key-trust').click();
      await expect(ok).toBeVisible({ timeout: 120_000 });
      await dialog.getByTestId('add-connection-done').click();

      const up = await connectionByName(api, 'Fake upload');
      expect(up).toMatchObject({ authMethod: 'ssh_uploaded', status: 'ok', secretSet: true });
      expect(await responseLeaks(['PRIVATE KEY', keyBody, 'scn-passphrase'])).toEqual([]);
      fakeGit(stand, 'rm -f /tmp/scn-upload /tmp/scn-upload.pub');
    });

    await test.step('5. a token revoked at the host: Test shows it, git fetch says "rejected by the host" (FR-1a, FR-11)', async () => {
      const conn = await connectionByName(api, 'Fake PAT');
      const vault = await createWorkspace(api, 'Vault');
      vaultId = vault.id;
      await setGrants(api, conn.id, [vaultId]);
      await attachRemote(api, vaultId, conn.id);
      const first = gitMain(vaultId, ['fetch', 'origin']);
      expect(first.status, first.stderr).toBe(0);
      expect(gitMain(vaultId, ['rev-parse', '--verify', 'refs/remotes/origin/dev']).status).toBe(0);

      setFakePat(stand, 'revoked-pat');
      try {
        await page.goto('/#/connections');
        await row(page, 'Fake PAT').getByTestId('connection-test').click();
        const box = page.getByTestId('test-connection-dialog');
        await box.getByTestId('connection-test-url').fill(FAKE_GIT_HTTP);
        await box.getByTestId('connection-test-run').click();
        await expect(box.getByTestId('connection-test-failed')).toContainText('Rejected by the host', { timeout: 120_000 });
        await box.getByRole('button', { name: 'Close' }).last().click();
        await expect(row(page, 'Fake PAT').getByTestId('connection-status')).toHaveText('Rejected by host');

        const fetch = gitMain(vaultId, ['fetch', 'origin']);
        expect(fetch.status).not.toBe(0);
        expect(fetch.stderr).toContain('Work Hub connection Fake PAT was rejected by the host');
      } finally {
        setFakePat(stand, pat);
      }
      expect(gitMain(vaultId, ['fetch', 'origin']).status).toBe(0);
    });

    await test.step('6. expose to the agent: a bad name is refused; on → in the session env; off → absent (FR-10)', async () => {
      await fakeLoginInContainer(api, vaultId);
      await page.goto('/#/connections');
      await row(page, 'Fake PAT').getByTestId('connection-edit').click();
      const edit = page.getByTestId('edit-connection-dialog');
      await edit.getByTestId('connection-expose').check();
      await edit.getByTestId('connection-expose-env').fill('1BAD');
      await edit.getByTestId('edit-connection-save').click();
      await expect(edit.getByRole('alert')).toBeVisible();
      await expect(edit).toBeVisible();
      const conn = await connectionByName(api, 'Fake PAT');
      expect(conn.exposeEnv).toBeNull();
      const reserved = await api.patch(`/api/v1/connections/${conn.id}`, { exposeEnv: 'WH_TOKEN' });
      expect(reserved.status).toBe(400);
      expect(reserved.body).toMatchObject({ error: 'invalid_env_name' });

      await edit.getByTestId('connection-expose-env').fill('SCN_TOKEN');
      await edit.getByTestId('edit-connection-save').click();
      await expect(edit).toHaveCount(0);
      await expect(row(page, 'Fake PAT').getByTestId('connection-exposed')).toBeVisible();
      expect((await connectionByName(api, 'Fake PAT')).exposeEnv).toBe('SCN_TOKEN');
      // An SSH connection cannot expose anything.
      const ssh = await connectionByName(api, 'Fake SSH');
      const notAllowed = await api.patch(`/api/v1/connections/${ssh.id}`, { exposeEnv: 'SCN_KEY' });
      expect(notAllowed.status).toBe(400);
      expect(notAllowed.body).toMatchObject({ error: 'expose_not_allowed' });

      const on = await openStream(api, vaultId, 'Exposed');
      expect(chatEnv(on.id)).toContain(`SCN_TOKEN=${pat}`);

      await api.expectStatus('PATCH', `/api/v1/connections/${conn.id}`, 200, { exposeEnv: null });
      await page.reload();
      await expect(row(page, 'Fake PAT').getByTestId('connection-exposed')).toHaveCount(0);
      const off = await openStream(api, vaultId, 'Hidden');
      const env = chatEnv(off.id);
      expect(env).not.toContain('SCN_TOKEN=');
      expect(env).not.toContain(pat);
    });

    await test.step('7. grants: the editor adds and removes workspaces (FR-5)', async () => {
      otherId = (await createWorkspace(api, 'Other')).id;
      await page.goto('/#/connections');
      // A connection with no grant offers "Grant…".
      await expect(row(page, 'Fake SSH').getByTestId('connection-grant')).toBeVisible();
      await expect(row(page, 'Fake PAT')).toContainText('1 workspace');

      await row(page, 'Fake PAT').getByTestId('connection-edit').click();
      const edit = page.getByTestId('edit-connection-dialog');
      const other = edit.locator(`[data-testid="grant-workspace"][data-workspace-id="${otherId}"]`);
      await expect(edit.locator(`[data-testid="grant-workspace"][data-workspace-id="${vaultId}"]`)).toBeChecked();
      await other.check();
      await edit.getByTestId('grants-save').click();
      await expect(edit.getByText('Saved.')).toBeVisible();
      expect((await connectionByName(api, 'Fake PAT')).grants.map((g) => g.workspaceId).sort()).toEqual([vaultId, otherId].sort());

      await other.uncheck();
      await edit.getByTestId('grants-save').click();
      await expect(edit.getByText('Saved.')).toBeVisible();
      expect((await connectionByName(api, 'Fake PAT')).grants.map((g) => g.workspaceId)).toEqual([vaultId]);
      await page.keyboard.press('Escape');
      await expect(edit).toHaveCount(0);
      await expect(row(page, 'Fake PAT')).toContainText('1 workspace');
    });

    await test.step('8. deleting a connection in use breaks its remote: "was deleted", the vault file is gone (FR-1)', async () => {
      const conn = await connectionByName(api, 'Fake PAT');
      expect(conn.usedBy).toEqual([expect.objectContaining({ workspaceId: vaultId, remoteName: 'origin' })]);
      const file = connectionSecretFile(stand, me.id, conn.id);
      expect(fs.existsSync(file)).toBe(true);
      // Without force the API refuses.
      const refused = await api.delete(`/api/v1/connections/${conn.id}`);
      expect(refused.status).toBe(409);
      expect(refused.body).toMatchObject({ error: 'connection_in_use' });

      await row(page, 'Fake PAT').getByTestId('connection-delete').click();
      const dialog = page.getByTestId('delete-connection-dialog');
      await expect(dialog.getByTestId('delete-connection-in-use')).toContainText('Vault · origin');
      await expect(dialog.getByTestId('delete-connection-confirm')).toHaveText('Delete and break 1 remote');
      await dialog.getByTestId('delete-connection-confirm').click();
      await expect(page.getByTestId('toast').filter({ hasText: 'Deleted Fake PAT.' })).toBeVisible({ timeout: 60_000 });
      await expect(row(page, 'Fake PAT')).toHaveCount(0);
      expect(fs.existsSync(file)).toBe(false);

      const fetch = gitMain(vaultId, ['fetch', 'origin']);
      expect(fetch.status).not.toBe(0);
      expect(fetch.stderr).toContain('Work Hub connection Fake PAT was deleted');
    });

    expect(offOrigin).toEqual([]);
  } finally {
    setFakePat(stand, FAKE_PAT);
    await context.close();
  }
});
